const body = $input.first().json.body || $input.first().json;

// Two kinds of heartbeat reach this webhook and they are not the same thing.
//
//  * WORKFLOW heartbeats carry workflow_id + workflow_name and describe one
//    n8n execution. They belong in workflow_runs.
//  * AGENT heartbeats come from the VPS agents (curl, type:'agent'). They have
//    no workflow_id because they are not n8n workflows. They belong on the
//    agents row, in last_run / last_output.
//
// The CLO-002 guard (audit C4) was right that anonymous rows must not pollute
// workflow_runs, but it tested for the wrong thing: it rejected every
// agent heartbeat too, so 100% of traffic failed and the fleet went dark for
// weeks with nothing recorded. Reject only genuinely unidentified callers.

const agentId = body.agent_id || body.agent || '';
const agentName = body.agent_name || '';
const wfId = body.workflow_id || '';
const wfName = body.workflow_name || '';

if (!agentId && !agentName && !wfId) {
  throw new Error('unidentified heartbeat: need agent_id/agent_name or workflow_id');
}

// The roster keys on a short lowercase slug ("priya"); the VPS sends a
// descriptive id ("product-agent") plus the display name. Prefer the name,
// which matches the slug, and fall back to the id.
const slug = (agentName || agentId).toLowerCase().replace(/[^a-z0-9]/g, '');

const isWorkflow = Boolean(wfId && wfName);
const now = new Date().toISOString();

return [{
  json: {
    kind: isWorkflow ? 'workflow' : 'agent',
    timestamp: body.timestamp || now,
    agent_id: slug,
    agent_id_raw: agentId,
    agent_name: agentName,
    workflow_id: wfId || null,
    workflow_name: wfName || null,
    status: body.status || 'unknown',
    outcome: body.outcome || '',
    summary: body.summary || '',
    next_run: body.next_run || '',
    duration_ms: body.duration_ms || 0,
    cost_usd: body.cost_usd || 0,
    api_calls: body.api_calls || 0,
    quality_score: body.quality_score || null,
    detail: body.detail || body.message || body.summary || '',
    raw: JSON.stringify(body)
  }
}];

const __helpers = this.helpers;
async function __httpRequest(opts) {
  const cfg = { method: opts.method || 'POST', url: opts.url, headers: opts.headers || {}, json: true, returnFullResponse: true, timeout: 15000 };
  if (opts.body) cfg.body = opts.body;
  try {
    const res = await __helpers.httpRequest(cfg);
    return res.body || res;
  } catch (err) {
    return { error: err.message };
  }
}
const d = $('Validate & Normalise').first().json;
const SERVICE_KEY = '{{SUPABASE_SERVICE_ROLE_KEY}}';
const H = {
  'apikey': SERVICE_KEY,
  'Authorization': 'Bearer ' + SERVICE_KEY,
  'Content-Type': 'application/json',
  'Prefer': 'return=minimal'
};

// Agent heartbeats update the agent's own row. They are deliberately NOT
// written to workflow_runs, which is one row per n8n execution.
if (d.kind === 'agent') {
  const out = d.summary || d.detail || d.outcome || '';
  await __httpRequest({
    method: 'PATCH',
    url: 'https://gojpffsrxybbpbdzzrvs.supabase.co/rest/v1/agents?id=eq.' + encodeURIComponent(d.agent_id),
    headers: H,
    body: { last_run: d.timestamp, last_output: out }
  });
  return [{ json: { logged: 'agent', agent_id: d.agent_id } }];
}

const payload = {
  workflow_id: d.workflow_id,
  workflow_name: d.workflow_name,
  agent_id: d.agent_id,
  duration_ms: d.duration_ms,
  api_calls: d.api_calls,
  cost_usd: d.cost_usd,
  outcome: d.outcome,
  outcome_count: 0,
  quality_score: d.quality_score,
  status: d.status,
  metadata: JSON.stringify({ source: 'status_update_webhook', detail: d.detail })
};
await __httpRequest({
  method: 'POST',
  url: 'https://gojpffsrxybbpbdzzrvs.supabase.co/rest/v1/workflow_runs',
  headers: H,
  body: payload
});
return [{ json: { logged: 'workflow' } }];
